  const syncData = useCallback(async (showLoader = true) => {
    if (!selectedUnit || !sheetUrl) return;
    if (showLoader) setIsSyncing(true);

    // Check local storage key specific to unit
    const storageKey = `sao_movements_${selectedUnit.id}`;

