  if (!url || !url.includes("exec")) return false;

  try {
    const response = await fetch(url, {
      method: 'POST',
      body: JSON.stringify({ 
        action: 'sendEmail', 
        to, 
        subject, 
        body 
      }),
      headers: { 'Content-Type': 'text/plain;charset=utf-8' },
    });

