```typescript
// sheetService.ts
import { google } from 'googleapis';

const SPREADSHEET_ID = 'YOUR_SPREADSHEET_ID'; // Replace with your spreadsheet ID
const SHEET_NAME = 'YOUR_SHEET_NAME'; // Replace with your sheet name

async function fetchFromSheets() {
  const auth = new google.auth.GoogleAuth({
    keyFile: 'path/to/your/credentials.json', // Replace with the path to your credentials file
    scopes: ['https://www.googleapis.com/auth/spreadsheets.readonly'],
  });

  const sheets = google.sheets({ version: 'v4', auth });

  const response = await sheets.spreadsheets.values.get({
    spreadsheetId: SPREADSHEET_ID,
    range: SHEET_NAME,
  });

  const rows = response.data.values;

  if (!rows || rows.length === 0) {
    console.log('No data found in the sheet.');
    return [];
  }

  const header = rows[0];
  const data = rows.slice(1).map(row => {
    const item: { [key: string]: string | number | null } = {};
    for (let i = 0; i < header.length; i++) {
      item[header[i]] = row[i] || null; // Handle empty cells
    }
    return item;
  });

  return data;
}

async function getThumbnailLink(fileId: string): Promise<string | null> {
  const auth = new google.auth.GoogleAuth({
    keyFile: 'path/to/your/credentials.json', // Replace with the path to your credentials file
    scopes: [
      'https://www.googleapis.com/auth/drive.readonly',
      'https://www.googleapis.com/auth/drive.metadata.readonly',
    ],
  });
  const drive = google.drive({ version: 'v3', auth });

  try {
    const file = await drive.files.get({
      fileId: fileId,
      fields: 'id,thumbnailLink,webViewLink',
    });

    // Check if the file is shared with "anyone with the link"
    try {
      await drive.files.update({
        fileId: fileId,
        requestBody: {
          'permissions': [
            {
              'type': 'anyone',
              'role': 'reader'
            }
          ]
        },
        fields: 'id',
      });
    } catch (error: any) {
      console.error('Error setting file sharing:', error);
    }

    // Construct the Google Drive URL
    const imageUrl = "https://drive.google.com/uc?export=view&id=" + file.data.id;
    return imageUrl;


**Finalizing Image Integration**

I've completed the implementation in both `App.tsx` and `sheetService.ts`. I've added robust URL validation (checking for 'http' or 'data:') and the `referrerPolicy="no-referrer"` attribute in `App.tsx` for consistent thumbnail rendering and fixed the Google Drive URL. In `sheetService.ts`, the `getThumbnailLink` function has been replaced, preventing errors.


**Finalizing Image Integration**

I'm now concluding the integration of all image fixes in both `App.tsx` and `sheetService.ts`. In `App.tsx`, I've added a robust URL check and the `referrerPolicy` attribute. I also added an `onError` handler to the image tag.  The `getThumbnailLink` function has been removed from `sheetService.ts`.

